/**
 * Model Switch Consent — PreModelSwitch hook (CC 2.1.251, #3789)
 *
 * The standing rule "no Fable spend without consent" had one enforcement point
 * before this hook: fable-spend-consent, a PreToolUse[Agent] gate that asks
 * before an agent SPAWN pins a Fable id. It could not see the other way onto
 * the premium tier, which is the session itself switching via `/model`, the
 * model picker, or the SDK's set_model. CC 2.1.251 added PreModelSwitch for
 * exactly that seam: the hook receives from_model/to_model and may answer
 * `permissionDecision: allow | deny | ask` like a PreToolUse hook, or exit 2
 * to block outright.
 *
 * Behavior:
 *   - to_model on the premium tier (Fable / Mythos, short or full id) and the
 *     session is NOT already on that tier  -> ask, with the measured re-cache
 *     cost in the reason when CC supplied one.
 *   - already on the premium tier (e.g. fable -> fable[1m])  -> allow silently;
 *     the spend decision was made when the session got there.
 *   - ORK_FABLE_OK=1  -> allow silently (same pre-consent switch as the spawn
 *     gate, so one env var covers both doors).
 *   - anything else   -> allow silently.
 *
 * Re-cache warning (claude.dev "Prompt caching is everything"): a mid-session
 * switch on a warm, large context rewrites the whole prompt cache on the new
 * model. Measured in model-switch.jsonl: 113 switches from 2026-08-29 to
 * 2026-09-29, 102 of them above 100k context, about $592 of estimated cache
 * writes. When the cache is warm and context_tokens exceeds
 * WARM_CONTEXT_WARN_TOKENS, every allowed switch carries one systemMessage line
 * naming the estimated cost and the cheaper path (finish on the current model,
 * or hand off through a subagent or a fresh session with a short plan). It
 * never asks or denies. The premium-tier ask already quotes the cost in its
 * reason, so that path adds no second line. This lives here, not in the
 * PostModelSwitch telemetry hook, because that hook is async: CC delivers an
 * async systemMessage on the NEXT turn, after the cache was already paid for.
 *
 * DELIBERATELY NOT gated on isBypassMode(), for the same reason the spawn gate
 * is not: `--dangerously-skip-permissions` turns off permission prompts, and
 * this is spend consent, not a permission. ORK_FABLE_OK=1 is the explicit
 * pre-consent path and stays explicit on purpose.
 *
 * Payload contract measured on 2.1.251 (2026-08-29), see lib/session-staleness.ts.
 *
 * @hook PreModelSwitch
 */

import type { HookInput, HookResult, HookContext } from '../types.js';
import { outputSilentSuccess, outputWarning } from '../lib/common.js';
import { NOOP_CTX } from '../lib/context.js';
import { isPremiumTierModel, readModelSwitch } from '../lib/session-staleness.js';
import type { ModelSwitchPayload } from '../lib/session-staleness.js';

const HOOK_NAME = 'model-switch-consent';

/** Above this many context tokens on a warm cache, a switch gets a re-cache warning. */
export const WARM_CONTEXT_WARN_TOKENS = 100_000;

function recacheWarning(sw: ModelSwitchPayload): string | null {
  if (!sw.promptCacheWarm || sw.contextTokens <= WARM_CONTEXT_WARN_TOKENS) {
    return null;
  }
  const from = sw.fromModel || 'the current model';
  const cost =
    sw.estimatedCacheWriteUsd > 0 ? `, estimated $${sw.estimatedCacheWriteUsd.toFixed(2)} (${sw.pricing || 'catalog'} pricing)` : '';
  return (
    `Switching ${from} -> ${sw.toModel} re-caches a warm ${sw.contextTokens.toLocaleString('en-US')}-token context${cost}. ` +
    `Cheaper: finish this task on ${from}, or hand the next step to a subagent or a fresh session with a short plan.`
  );
}

/** Allow the switch, with the re-cache warning when one applies. */
function allow(sw: ModelSwitchPayload): HookResult {
  const warning = recacheWarning(sw);
  return warning ? outputWarning(warning) : outputSilentSuccess();
}

export function modelSwitchConsent(input: HookInput, ctx: HookContext = NOOP_CTX): HookResult {
  const sw = readModelSwitch(input);

  if (!sw.toModel) {
    return outputSilentSuccess();
  }

  if (!isPremiumTierModel(sw.toModel)) {
    return allow(sw);
  }

  if (isPremiumTierModel(sw.fromModel)) {
    ctx.log(HOOK_NAME, `premium-tier switch within tier allowed: ${sw.fromModel} -> ${sw.toModel}`);
    return allow(sw);
  }

  if (process.env.ORK_FABLE_OK === '1') {
    ctx.log(HOOK_NAME, `premium-tier switch allowed (ORK_FABLE_OK=1): ${sw.fromModel} -> ${sw.toModel}`);
    return allow(sw);
  }

  const costClause =
    sw.estimatedCacheWriteUsd > 0
      ? ` Re-caching the current ${sw.contextTokens.toLocaleString('en-US')} tokens of context is estimated at $${sw.estimatedCacheWriteUsd.toFixed(2)} (${sw.pricing || 'catalog'} pricing).`
      : '';
  const from = sw.fromModel || 'the current model';

  ctx.log(HOOK_NAME, `escalating premium-tier switch to user consent: ${from} -> ${sw.toModel} (source=${sw.source || '?'})`);
  return {
    continue: true,
    suppressOutput: true,
    hookSpecificOutput: {
      hookEventName: 'PreModelSwitch',
      permissionDecision: 'ask',
      permissionDecisionReason:
        `Switching this session from "${from}" to "${sw.toModel}" puts every following turn on ` +
        `Claude Fable 5 pricing, $10/$50 per MTok (2x Opus output).${costClause} ` +
        `Approve to spend deliberately, or deny to stay on "${from}". ` +
        `Pre-consent for this session with ORK_FABLE_OK=1.`,
    },
  };
}
